content.text:
I found one fault: the network path from `search` to `geo` is losing packets, and that is what makes `/hotels` slow for users. Other services checked out, including profile, reservation, rate and geo's own handling. No errors appeared anywhere, so the impact shows as latency, not failures.

```json
{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT 'abn' AS p, * FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client' UNION ALL SELECT 'norm' AS p, * FROM normal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client'), g AS (SELECT parent_span_id, duration FROM abnormal_traces WHERE service_name='geo' AND attr_span_kind='Server' UNION ALL SELECT parent_span_id, duration FROM normal_traces WHERE service_name='geo' AND attr_span_kind='Server') SELECT c.p, c.duration>1e9 AS slow, count(*) AS n, count(g.parent_span_id) AS with_geo_server, quantile_cont(g.duration,0.5)/1e6 AS geo_srv_p50_ms, quantile_cont(c.duration,0.5)/1e6 AS client_p50_ms FROM c LEFT JOIN g ON g.parent_span_id = c.span_id GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Abnormal search→geo calls: 56 slow (p50 1.8 s), only 7 reached a geo server span; normal calls mostly matched, geo handler about 0.15 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.time AS client_start, g.time AS geo_start, (epoch(g.time)-epoch(c.time))*1000 AS start_offset_ms, c.duration/1e6 AS client_ms, g.duration/1e6 AS geo_ms FROM abnormal_traces c JOIN abnormal_traces g ON g.parent_span_id=c.span_id AND g.service_name='geo' WHERE c.service_name='search' AND c.span_name='geo.Geo/Nearby' ORDER BY c.time",
          "claim": "Delay occurs before geo receives the request: start offsets of about 1.75–3.3 s in retransmission-like steps, while geo's handler takes 0.1–0.2 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1,2,3",
          "claim": "User-facing frontend HTTP /hotels p50 is about 1,816 ms, p95 about 3,308 ms, versus about 5.7 ms normally; no error status."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.time, c.duration/1e6 AS search_client_geo_ms, (SELECT count(*) FROM abnormal_traces g WHERE g.parent_span_id=c.span_id AND g.service_name='geo') AS geo_server_spans FROM abnormal_traces c WHERE c.service_name='search' AND c.span_name='geo.Geo/Nearby' AND c.attr_span_kind='Client' AND c.duration>1e9 ORDER BY c.time",
          "claim": "Slow search→geo client spans of 1.6–3.3 s mostly have no matching geo server span, so search waits on the lossy connection."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name='search.Search/Nearby' GROUP BY 1,2,3",
          "claim": "search.Search/Nearby server p95 about 3,295 ms, and frontend's client call to it is about 3,300 ms, so the delay passes up to frontend."
        }
      ]
    }
  ]
}
```

